  /* (0.16.7) 공개 화면에 유의 사항이 안 보이면(주문 중 '비공개'·칸 없음·글 없음) 샵매니저 상품 수정 화면(로그인)의 bookDesc로 — 정범님 10/17 '주문확인요청·오늘 출고 유의 사항 실수 없게' · 점검에서 공개 화면에 칸이 없던 순간 '칸이 없음'으로 남아 빠진 것(요가해부학 컬러링북) */
  if (!info._box || !info.hasNote) { try { const sc = await p.evaluate(async (lid) => { const P = window.ReadnowProducts; if (!P || !P.parseScmEditNote) return { err: '상품 공용 파일 0.15.1 아님' }; const r = await fetch('/scm/wrecord.aspx?action=2&bookid=0&UpdateItemId=' + lid, { credentials: 'include', cache: 'no-store' }); if (/\/login\/|wlogin/i.test(r.url)) return { login: false }; const d = new DOMParser().parseFromString(await r.text(), 'text/html'); return P.parseScmEditNote(d); }, String(lid));
      if (sc && sc.found) { const keepTop = (info.photos || []).filter((x) => x.where === 'top'); info = { ...info, note: sc.note, hasNote: sc.hasNote, photos: [...keepTop, ...sc.photos], sellerPhotoCount: sc.photos.length, photoDiff: sc.photos.length > 0 || !!info.photoDiff, found: true, _box: true, src: 'scm' }; } else if (sc && sc.login === false) log('유의 사항: 샵매니저 로그인이 풀려 수정 화면을 못 읽음', lid); } catch (e) { log('유의 사항: 샵매니저 수정 화면 읽기 실패', lid, e.message); } }
  const ref = C('prd_used_info').doc(String(lid)); at = at || nowIso();
