    if (left.length && !to) { if (Date.now() - J.pAt > 4000) { J.pAt = Date.now(); const sg = `${prog.done}|${prog.fail}|${prog.gone}`; if (J.st && J.sg !== sg) { J.sg = sg; J.st(prog.fail ? 'warn' : 'info', `시장 다시 읽는 중 — 읽음 ${prog.done} · 못 읽음 ${prog.fail} · 목록에서 빠짐 ${prog.gone} · 남음 ${prog.left} / ${prog.n}권`, { big: 1 }); } J.bAt = Date.now(); await J.ref.set({ prog, progAt: nowIso(), beatAt: nowIso(), claim: { pc: 'cloud', at: nowIso() }, doneL: [...J.done], failL: [...J.fail], noListNow: noList, uploadedAt: FV.serverTimestamp() }, { merge: true }).catch(() => {}); } continue; }
