      const R = await ghRunsDay(day, fetchF); if (R.open && day === kstDay(Date.now() - 864e5)) break; /* 어제 실행이 아직 도는 중 — 다음 회차에 */ const ym = day.slice(0, 7); const ref = C('app_settings').doc('costs_gh_' + ym);
