const ML_VER = 1;
const shard = (arr, n) => { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; };
let _l2u = null, _l2uAt = 0; /* (0.11.0) 상품번호→상품코드 표를 1시간 기억 — 하루 일마다 상품 전체를 여러 번 읽던 것 */
