  for (let i = 0; i < ids.length; i += 300) { const part = ids.slice(i, i + 300); const [g1, g2] = await Promise.all([db.getAll(...part.map((x) => C('prd_books').doc(x)), { fieldMask: ['categories', 'pubDate', 'aladinItemId'] }), db.getAll(...part.map((x) => C('prd_book_metrics').doc(x)), { fieldMask: ['buyerDist', 'relationBuyIds', 'salesPoint'] })]);
    g1.forEach((g) => { if (!g.exists) return; const v = g.data() || {}; B.set(g.id, { cat: v.categories && v.categories[0] && v.categories[0].path, ym: String(v.pubDate || '').slice(0, 7) }); if (v.aladinItemId) byItem.set(String(v.aladinItemId), g.id); }); g2.forEach((g) => { if (!g.exists) return; const v = g.data() || {}; M.set(g.id, { salesPoint: v.salesPoint, buyerDist: v.buyerDist || null, relationBuyIds: (v.relationBuyIds || []).map((r) => ({ aladinItemId: r && r.aladinItemId })) }); }); slMemCk('ourItems'); } /* (cloudmem 11/13) 함께 산 책은 번호만 남김(제목 등 다른 칸은 안 씀) */
