  for (let i = 0; i < lids.length; i += 300) { try { const got = await db.getAll(...lids.slice(i, i + 300).map((x) => C('pur_matches').doc(x)), { fieldMask: ['cost', 'kind'] }); got.forEach((g) => { const v = g.exists ? g.data() || {} : null; if (v && v.kind !== 'none' && v.cost != null && Number.isFinite(+v.cost)) COST.set(g.id, +v.cost); }); } catch (e) { break; } }
