    let oursN = 0; if (OI) { const d1 = SLc.dayN(day), d0 = d1 - 60; const R0 = SLc.ourPanel(OI.items, d0, d1, { kw, rare: SLc.rareOf(setsC, 'ours'), look: OI.look, U: OI.U }, FP); oursN = R0.length; rows = rows.concat(R0); }
    const ex = SLc.explore(rows, { extra: (H0.comp && H0.comp.pending) || [] });
    /* (front2 · 정범님 11/12 밤) 우리 숍 ⬆ 앞 페이지 올리기 실험(N12 — 무작위 대조군 A/B 먼저)을 가설 원장 점수의 사전 분포로 — 숍 단위 상관 + 우리 실험 */ let FBE = null; try { FBE = ((await C('app_settings').doc('front_bump_eval').get()).data()) || null; } catch (e) {} const PRI = SLc.bumpPrior ? SLc.bumpPrior(FBE) : null;
    const L2 = SLc.hypEvolve(H0.comp || null, ex, day, PRI ? { prior: PRI } : undefined); const F3 = [...new Set((L2.best || []).filter((h) => !h.f.includes('*')).map((h) => h.f))].slice(0, 3); const oos = SLc.oosScore(rows, F3, 'g3');
    /* (sell3) 채움 기준별(10·30·50%) — 새 재료 특징만 · 우리 숍 줄 빼고(우리 줄은 분야·SP가 늘 차 있어 기준과 무관) */ if (SLc.fillSens) { try { const t0 = Date.now(); out.sens = { by: SLc.fillSens((t) => preC.flatMap(([g, P]) => SLc.panelFrom(g, P, { rare: SLc.rareOf(setsC, g), kw, bigPub, minFill: t }))), ms: 0 }; out.sens.ms = Date.now() - t0; } catch (e) { out.sens = { err: e.message }; } }
    const fAge = {}; for (const r of rows) { if (r.g === 'ours' || !r.fill) continue; const a = SLc.dayN(day) - r.d; const k = a <= 7 ? '0~7일 전' : a <= 30 ? '8~30일 전' : '31일 넘게 전'; const z = fAge[k] || (fAge[k] = { n: 0, sp: 0, ym: 0, pub: 0, cat: 0, cov: 0 }); z.n++; for (const f of ['sp', 'ym', 'pub', 'cat', 'cov']) z[f] += r.fill[f] || 0; } for (const z of Object.values(fAge)) for (const f of ['sp', 'ym', 'pub', 'cat', 'cov']) z[f] = Math.round(z[f] / z.n * 1000) / 1000;
    out.comp = { shops: preC.length, oursRows: oursN, rows: rows.length, kw, fillAge: fAge, bigPub: bigPub.size, newFeats: [...new Set(rows.filter((r) => r.g !== 'ours').flatMap((r) => Object.keys(r.x).filter((k) => SLc.NEWF && SLc.NEWF.test(k))))].slice(0, 40), tests: ex.tests, sig: ex.sig, sigRep: ex.sigRep, top: ex.top.slice(0, 20).map((t) => ({ ...t, ft: SLc.featT(t.f), yt: SLc.YT[t.y] || t.y })), ledger: L2.sum, best: L2.best, pending: L2.pending, oos,
      note: '숍 안에서만 견줌(고정효과) · 지금 판매·다음 등록·재고를 빼고 · 숍 안 시간 돌려 섞기 순열 · BH 보정 q<0.1 · 앞뒤 절반 같은 방향 = 재현 · 관계일 뿐 원인이라고 못 함 · SP·출판사·출간 연월은 수집 적응 엔진이 채운 만큼(지금 SP 값 — 그날 SP 아님) · 분야는 우리 책·국중 KDC로 이은 만큼 · 표지는 우리 책과 이어진 것만(서가 표지 셈)' };
