  const A = SLc.audStudy(OI.items.filter((x) => x.id), { now: SLc.dayN(day) }); const H0 = ((await C('app_settings').doc('seller_hyp').get().catch(() => null)) || { data: () => null }).data() || {}; const L2 = SLc.hypEvolve(H0.aud || null, { all: A.all }, day);
