  /* ② 책마다 팔린 근거 */
  const BE = new Map(); for (const x of SOLD) { const bid = x[5]; if (!bid) continue; let o = BE.get(bid); if (!o) BE.set(bid, (o = { c: [], e: [], s: {} })); (CONF.includes(x[1]) ? o.c : o.e).push([x[2], x[4]]); o.s[x[1]] = (o.s[x[1]] || 0) + 1; }
