    let tg = 0, back = 0, out = 0, tOnly = true; for (const e of evs) { const [a, b] = String(e).split('|')[1].split('>'); if (OOP_O.has(a) || OOP_O.has(b)) { out++; if (a === 'P' || a === 'J' || b === 'P' || b === 'J') tOnly = false; } if ((OOP_A.has(a) && OOP_O.has(b)) || (OOP_O.has(a) && OOP_A.has(b))) tg++; if (OOP_O.has(a) && OOP_A.has(b)) back++; }
