  for (const x of books) { const cg = x.comic ? 'comic' : 'etc', ub = UBk(x.u); const K = [`${x.k}|${ub}|${cg}`, `${x.k}|${ub}|*`, `${x.k}|*|*`, `sp|${x.k}|${SPk(x.sp)}`, `tg|${x.k}|${Math.min(3, x.tg)}`]; if (x.cat) K.push(`cat|${x.k}|${x.cat}`); if (x.k === 'oop') K.push(`cur|${x.cur}`); if (x.k === 'was') K.push(`was|${x.tOnly ? 'T' : 'PJ'}`); for (const key of K) addD(key, x); }
  const R3 = (v) => Math.round(v * 1000) / 1000; const Q = (a) => { if (!a.length) return null; const s0 = Float64Array.from(a).sort(); const n = s0.length; return [n, R3(qa(s0, 0.5)), R3(qa(s0, 0.75)), R3(qa(s0, 0.9)), R3(a.filter((r) => r >= 1).length / n), R3(a.filter((r) => r >= 2).length / n), R3(s0[n - 1])]; };
