  const pick = (x) => ({ b: x.b, i: x.i, t: x.t, c: x.cat, k: x.k, a: x.cur, u: x.u, sp: x.sp, lp: x.lp, tg: x.tg, bk: x.back, to: x.tOnly, cm: R3(x.cm), cp: x.cp, cn: x.cn, em: R3(x.em), ep: x.ep, en: x.en, md: x.md == null ? null : R3(x.md), g1: x.g1, s: x.s, o: x.our, cx: x.comic, ev: x.ev.slice(-6) });
  const ranked = books.filter((x) => x.cm > 0 || x.em > 0).sort((a, b) => Math.max(b.cm, b.em) - Math.max(a.cm, a.em) || b.cn - a.cn); let top = ranked.slice(0, 1500).map(pick);
