async function spPanelTick() { const st = C('app_settings').doc('sp_panel'); let P = (await st.get()).data() || {};
  if (!Array.isArray(P.isbns) || !P.isbns.length) { const ms = await C('prd_book_metrics').select('salesPoint', 'availability').get(); const IB = new Map(); (await C('prd_books').select('isbn13').get()).forEach((d) => { const v = d.data() || {}; if (/^97[89]\d{10}$/.test(String(v.isbn13 || ''))) IB.set(d.id, v.isbn13); }); /* (0.19.2) 시장 지표 문서 번호는 도서 번호(ISBN이 아님) — 도서 기록의 isbn13으로 이음 */ const band = [[], [], [], [], []], out = []; ms.forEach((d) => { const v = d.data() || {}; const i0 = IB.get(d.id) || (/^isbn_(97[89]\d{10})$/.exec(d.id) || [])[1]; const isbn = i0 ? [null, i0] : null; if (!isbn) return; if (/절판|품절/.test(String(v.availability || ''))) out.push(isbn[1]); else if (v.salesPoint != null) { const sp = +v.salesPoint; band[sp < 50 ? 0 : sp < 200 ? 1 : sp < 1000 ? 2 : sp < 5000 ? 3 : 4].push(isbn[1]); } });
    const pick = (a, n) => { const b = a.slice(); for (let i = b.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [b[i], b[j]] = [b[j], b[i]]; } return b.slice(0, n); }; const isbns = [...new Set([...band.flatMap((a) => pick(a, 50)), ...pick(out, 50)])]; P = { isbns, made: nowIso(), bands: band.map((a) => a.length), outN: out.length }; await st.set({ ...P, ...W() }, { merge: true }); }
  const day = new Date(Date.now() + 9 * 3600e3).toISOString().slice(0, 10); const hh = new Date(Date.now() + 9 * 3600e3).getUTCHours(); if (hh < 4) return { wait: 'before 4' };
  const dref = C('sp_daily').doc(day); const cur = (await dref.get()).data() || {}; const have = cur.v || {}; const todo = P.isbns.filter((x) => !have[x]).slice(0, 60); if (!todo.length) return { done: Object.keys(have).length };
  /* (ttb1 11/11) 🛑 알라딘 OpenAPI(TTB) 종료(2026-10-30 · 11/01부터 모든 책에 오류 999) → TTB는 묻지 않음(헛호출 0) · 대체 출처 차례:
   *  ① 우리 시장 지표(prd_book_metrics — 로거·수집기가 이미 읽은 알라딘 상품 화면 값) 36시간 안 = 'mkt' (새 요청 없음)
   *  ② 남은 책만 클라우드가 알라딘 공개 상품 화면을 읽음(로그인 정보 없이 · 한 회차 20권 · 1.5초 간격) = 'pg' — 로거·사무실 PC 몫을 새로 만들지 않음
   *  sp_daily.v[isbn] = [SP, 새상품 판매가, 재고 상태 글, 출처 'mkt'|'pg'|'list'(adapt1 11/11 공개 검색 목록 한 쪽)] (R06은 [0]만 씀) */
  const v = {}; let fb = 0, pg = 0, bad = 0, lst = 0; const lim = Date.now() - 36 * 3600e3;
  try { for (let k = 0; k < todo.length; k += 30) { const part = todo.slice(k, k + 30); const bs = await C('prd_books').where('isbn13', 'in', part).select('isbn13').get(); const ids = bs.docs.map((d) => [d.id, (d.data() || {}).isbn13]); if (!ids.length) continue; const ms = await db.getAll(...ids.map(([id]) => C('prd_book_metrics').doc(id)));
      ms.forEach((m, j) => { const x = m.exists ? m.data() || {} : null; const at = x ? Date.parse(x.lastCheckedAt || '') || 0 : 0; const i = ids[j][1]; if (x && x.salesPoint != null && at > lim && !v[i]) { v[i] = [+x.salesPoint, x.priceSales != null ? +x.priceSales : null, x.availability && x.availability !== 'onSale' ? String(x.availability).slice(0, 20) : null, 'mkt']; fb++; } }); } } catch (e) { log('SP 표본: 시장 지표로 채우기 실패', e.message); }
  const rest = todo.filter((i) => !v[i]).slice(0, 20); let pErr = null; let agS = null;
  if (rest.length) { let p = null; try { p = await getPage(); } catch (e) { pErr = '클라우드 화면을 못 엶: ' + String(e.message || e).slice(0, 80); }
    const agP = p && typeof agChoose === 'function' ? await agChoose('sp_panel', AG_SEED.sp_panel) : null; const agUse = agP && agP.mid === 'page' ? 'page' : 'list'; agS = { list: { n: 0, ok: 0, cost: 0 }, page: { n: 0, ok: 0, cost: 0 } }; /* (adapt9) 🔄 목록 길이 무너지면(장부 챔피언 = 상품 화면) 목록을 건너뛰어 한 쪽 아낌 · ε만큼은 목록도 다시 시험 */
    if (p) for (const isbn of rest) { try { /* (adapt1 11/11 정범님 '이 길로 얻을 수 있는 건 이 길로') 공개 검색 결과 목록 한 쪽 먼저(상품 화면까지 2쪽 → 1쪽) · 표지 ISBN이 같은 줄이 없을 때만 상품 화면 */ let x = null; if (agUse === 'list') { try { x = typeof alListItem === 'function' ? await alListItem(p, isbn) : null; } catch (e) { x = null; } agS.list.n++; agS.list.cost++; } const agPg = !x; if (x) { lst++; agS.list.ok++; } else x = await alPubItem(p, { isbn }); if (agPg) { const sx = agUse === 'list' ? agS.list : agS.page; if (agUse === 'page') sx.n++; sx.cost++; if (x && !x.gate && x.salesPoint != null) sx.ok++; } if (x && !x.gate && x.salesPoint != null) { v[isbn] = [+x.salesPoint, x.priceSales != null ? +x.priceSales : null, String(x.stockStatus || '').slice(0, 20) || null, x.src === 'list' ? 'list' : 'pg']; pg++; } else { v[isbn] = [null, null, x && x.gate ? 'gate' : x ? 'nosp' : 'none', 'pg']; bad++; } } catch (e) { bad++; pErr = String(e.message || e).slice(0, 80); } await sleep(1500); } }
  if (agS && agS.list && (agS.list.n || agS.page.n) && typeof agObs === 'function') { for (const k of ['list', 'page']) if (agS[k].n) await agObs('sp_panel', AG_SEED.sp_panel, k, agS[k]); }
  await dref.set({ day, v, n: FV.increment(fb + pg), bad: FV.increment(bad), ...(fb ? { fromMkt: FV.increment(fb) } : {}), ...(pg ? { fromPage: FV.increment(pg) } : {}), ...(lst ? { fromList: FV.increment(lst) } : {}), at: nowIso(), ...W() }, { merge: true });
  const errNow = !fb && !pg && (bad || pErr) ? `시장 지표·공개 상품 화면 모두 못 채움${pErr ? ' — ' + pErr : ''}` : null; await st.set({ lastDay: day, lastAt: nowIso(), err: errNow, ...(errNow ? { errAt: nowIso() } : {}), ttbEnded: TTB_END, src: `${TTB_END_MSG} → 대체: 시장 지표(36시간 안) → 알라딘 공개 상품 화면`, ttbBadSince: null }, { merge: true }); return { ok: 0, fb, pg, bad }; }
