const ENGX_MEM_N = 600; /* 문서 하나에 상품 600개(1MB 아래) */
async function engMemLoad(id, n) { const out = []; for (let i = 0; i < (n || 0); i++) { const d = await C('eng_exp_m').doc(`${id}_${String(i).padStart(2, '0')}`).get(); if (d.exists) out.push(...((d.data() || {}).L || [])); } return out; }
