    if (EF0.noLossMode === undefined) { try { await C('app_settings').doc('eng_fence').set({ noLossMode: true, noLossAt: nowIso(), noLossBy: 'cloud', noLossWhy: '정범님 11/09 밤 — 연구·엔진 실험이 값을 내려 손해를 보는 일을 모두 멈춤(기본 켬 · 관찰만)', ...W() }, { merge: true }); log('🧪 무손해 모드를 켬(설정에 없어 기본값을 적음)'); } catch (e) { res.noLossErr = e.message; } }
