    let fromMs = Date.now(); for (const L of MEM.values()) for (const m of L) { const t = Date.parse(m.at || ''); if (t && t < fromMs) fromMs = t; } for (const [id, h] of H) if (h.state === 'end' && h.startAt) fromMs = Math.min(fromMs, Date.parse(h.startAt) || fromMs); const { avg: avgRev, sales } = await engAvgRev(E.revDays, fromMs); const limit = ML.dayLossLimit(avgRev, E); res.avgRev = avgRev; res.limit = limit; const fenceNow = {};
