    sum.ms = Date.now() - t0; await C('app_settings').doc('eng_wires').set(sum); WIRE.day = today; log('🔌 배선 그림자', Object.entries(sum.w).map(([k, x]) => `${k} 읽음 ${x.reads} · 바뀜 ${Object.values(x.would).reduce((a, b) => a + b, 0)}`).join(' / ')); return { n: Object.keys(sum.w).length, ms: sum.ms };
