/* (0.31.0) 📊 시장 지표 장면 수 — 정범님 10/21: 상품마다 시장 지표(온라인 중고 첫 페이지 통째)를 몇 장면 모았는지 · 처음부터 전부 셈(prd_metric_changes kind 'usedListings')
 *  mkt_snapcnt/c{0..15}.m[bookId] = [장면 수, 처음 때, 마지막 때] · 30분마다 지난번 뒤로만(처음엔 맨 처음부터 — 8분씩 이어서) · 아무것도 지우지 않음 */
let MC_BUSY = false; async function mktCountTick() { if (MC_BUSY) return; MC_BUSY = true; const t0 = Date.now();
  try { const stRef = C('app_settings').doc('mkt_snapcnt_state'); const st = (await stRef.get()).data() || {}; let cur = st.cursor || '2000-01-01'; const sig = new Map(); const dirty = new Set(); const load = async (i) => { if (!sig.has(i)) { const d = await C('mkt_snapcnt').doc('c' + i).get(); sig.set(i, (d.exists && d.data().m) || {}); } return sig.get(i); }; let n = 0, all = 0;
    for (;;) { if (Date.now() - t0 > 8 * 60e3) break; const qs = await C('prd_metric_changes').where('at', '>', cur).orderBy('at').limit(1000).select('bookId', 'at', 'kind').get(); if (qs.empty) break;
      for (const d of qs.docs) { const v = d.data() || {}; all++; if (v.at) cur = v.at; if (v.kind !== 'usedListings' || !v.bookId) continue; const bid = String(v.bookId); const i = mtH(bid, MT.SIG); const M = await load(i); const at = String(v.at || '').slice(0, 16); const x = M[bid] || (M[bid] = [0, at, at]); x[0]++; if (!x[1] || at < x[1]) x[1] = at; if (at > x[2]) x[2] = at; dirty.add(i); n++; }
      if (qs.size < 1000) break; }
    /* (0.31.2) 정범님 10/21: 주문 때 읽은 시장(shp_market — 판매 완료 시점 · 북스킹이 있던 자리 포함)도 셈 → 배열 [3]=판매 때 장면 수 · [4]=마지막 판매 때 */
    let cur2 = st.cursor2 || '2000-01-01', n2 = 0; for (;;) { if (Date.now() - t0 > 8 * 60e3) break; const qs = await C('shp_market').where('at', '>', cur2).orderBy('at').limit(1000).select('bookId', 'at').get(); if (qs.empty) break;
      for (const d of qs.docs) { const v = d.data() || {}; if (v.at) cur2 = v.at; if (!v.bookId) continue; const bid = String(v.bookId); const i = mtH(bid, MT.SIG); const M = await load(i); const at = String(v.at || '').slice(0, 16); const x = M[bid] || (M[bid] = [0, null, null]); x[3] = (x[3] || 0) + 1; if (!x[4] || at > x[4]) x[4] = at; dirty.add(i); n2++; }
      if (qs.size < 1000) break; }
    for (const i of dirty) await C('mkt_snapcnt').doc('c' + i).set({ m: sig.get(i), at: nowIso(), uploadedAt: FV.serverTimestamp() });
    await stRef.set({ cursor: cur, cursor2: cur2, lastN2: n2, total2: (st.total2 || 0) + n2, lastRun: nowIso(), lastN: n, lastAll: all, total: (st.total || 0) + n, ms: Date.now() - t0, caughtUp: Date.now() - t0 <= 8 * 60e3 }, { merge: true }); if (n || n2) log(`📊 시장 지표 장면 셈: +${n}장면 · 판매 때 +${n2} (훑은 변경 ${all}건)`); }
  catch (e) { log('📊 시장 지표 장면 셈 실패', e.message); } finally { MC_BUSY = false; } }
