  const RB = new Set(st.rebuiltDays || []); const SPL = ML.mlSplitDays ? ML.mlSplitDays(lab, [...RB]) : null; const skipD = new Set(SPL ? SPL.wait : []); const rbK = Math.max(1, Math.round(1 / (ML.REBUILT_W || 1)));
  for (const d of lab) { if (skipD.has(d)) continue; const rows = await mlLoadDay(d); if (!rows) continue; const y = mlLabel(ML, rows, d, sales); const st1 = RB.has(d) ? stride * rbK : stride; rows.forEach((r, i) => { if (i % st1) return; const x = ML.feats(r); if (!x) return; X.push(x); Y.push(y[i]); R0.push(r); D.push(d); }); }
  res.split = SPL ? { mode: SPL.mode, val: SPL.val.length ? [SPL.val[0], SPL.val[SPL.val.length - 1]] : null, wait: SPL.wait.length, rebuiltTrain: SPL.train.filter((d) => RB.has(d)).length, w: ML.REBUILT_W } : null;
  if (X.length < 200) { await ST.set({ learn: { day: today, state: 'wait', why: `배울 줄 ${X.length}개 — 200개부터`, at: nowIso() } }, { merge: true }); return { ...res, wait: true, rows: X.length }; }
