const CONS_CV = 2;
const consCatName = (cats) => { const c0 = Array.isArray(cats) ? cats[0] : null; const p = Array.isArray(c0) ? c0 : (c0 && c0.path) || []; return p.length > 1 ? p.slice(0, 2).map((x) => String(x).trim()).join(' > ') : null; };
