      if (took) { up['workers.' + took + '.to'] = pick.inFlight != null ? pick.inFlight : pick.from; up['workers.' + took + '.lost'] = D.nowIso(); if (pick.inFlight != null) { const fk = (x.keys || []).slice(pick.inFlight, pick.from); if (fk.length) up.failK = FVx.arrayUnion(...fk); } }
